"""Dashboard UI. Authentication and persistence are enforced by cms.py."""
PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Content Dashboard | Likitha Sports</title><link rel="icon" href="/logo.png?v=2"><link rel="stylesheet" href="/assets/tailwind.css?v=1"><style>
:root{--navy:#0b1e55;--green:#27bb36;--ink:#172443;--muted:#68748d;--line:#dfe5ef;--bg:#f3f6fb}*{box-sizing:border-box}body{margin:0;font:14px/1.6 Arial,sans-serif;background:var(--bg);color:var(--ink)}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{cursor:wait;opacity:.6}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid var(--green);outline-offset:3px}[hidden]{display:none!important}.shell{min-height:100vh;display:grid;grid-template-columns:245px 1fr}.sidebar{background:var(--navy);color:white;padding:28px 22px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column}.brand{padding:9px;background:white;border-radius:5px}.brand img{width:100%;display:block}.sidebar small{font-size:9px;letter-spacing:2px;color:#aebddc;display:block;margin:32px 12px 13px}.side-tabs{display:grid;gap:8px}.side-tabs button{background:transparent;border:0;padding:12px 15px;color:#d4def2;text-align:left;border-radius:5px}.side-tabs button[aria-selected=true]{background:#ffffff14;color:white;border-left:3px solid var(--green)}.side-bottom{margin-top:auto;font-size:11px;color:#b5c3df;padding:20px 12px 0}.side-bottom a{display:block;margin-top:12px;color:white}.top{background:white;border-bottom:1px solid var(--line);padding:20px 36px;display:flex;align-items:center;justify-content:space-between;gap:20px}.top strong{font-size:12px}.top div{display:flex;gap:10px;align-items:center}.btn{border:1px solid transparent;background:var(--navy);color:white;padding:10px 17px;border-radius:4px;font-size:12px;font-weight:bold}.btn.green{background:var(--green);color:var(--navy)}.btn.outline{background:white;border-color:var(--line);color:var(--navy)}.btn.danger{background:#fff0f0;color:#9f2525;border-color:#f2d1d1}.main{max-width:1120px;margin:auto;padding:34px 36px 80px}.eyebrow{font-size:10px;letter-spacing:1.5px;color:#1b7d29;font-weight:bold;margin:0 0 8px}h1{color:var(--navy);font-size:32px;letter-spacing:-1.2px;line-height:1.2;margin:0 0 10px}h2{font-size:19px;color:var(--navy);letter-spacing:-.5px;margin:0 0 6px}p{margin:0 0 17px}.muted{color:var(--muted);font-size:12px}.heading{display:flex;align-items:center;justify-content:space-between;gap:25px;margin-bottom:25px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin-bottom:25px}.stat{background:white;border:1px solid var(--line);border-radius:5px;padding:16px 20px}.stat b{font-size:23px;color:var(--navy);display:block}.stat span{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:1px}.panel{background:white;border:1px solid var(--line);border-radius:6px;padding:28px;margin-bottom:22px}.panel-head{display:flex;justify-content:space-between;align-items:start;gap:15px;margin-bottom:22px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.full{grid-column:1/-1}label{display:block;font-size:11px;font-weight:bold;color:var(--navy)}input:not([type=checkbox]):not([type=file]),textarea,select{display:block;width:100%;border:1px solid #ccd5e4;border-radius:4px;background:#fbfcfe;padding:11px 12px;color:var(--ink);margin-top:6px;font-size:13px}textarea{min-height:92px;resize:vertical}input[type=checkbox]{accent-color:var(--green)}.hint{font-size:10px;color:var(--muted);margin:6px 0 0}.editor-layout{display:grid;grid-template-columns:230px 1fr;gap:20px}.service-list{display:grid;gap:7px;align-content:start}.service-list button{padding:12px;text-align:left;background:white;border:1px solid var(--line);border-radius:4px;font-size:11px;color:var(--navy)}.service-list button.active{background:var(--navy);color:white}.service-list button span{display:block;font-size:9px;opacity:.65}.image-editor{display:grid;grid-template-columns:150px 1fr;gap:18px;align-items:center;margin:20px 0}.preview{width:150px;height:100px;object-fit:cover;background:var(--bg);border:1px solid var(--line);border-radius:4px}.image-empty{width:150px;height:100px;display:grid;place-items:center;background:var(--bg);border:1px dashed #bdc9dd;font-size:10px;color:var(--muted);border-radius:4px}.upload-label{display:inline-block;cursor:pointer;background:var(--bg);padding:8px 13px;border:1px solid var(--line);border-radius:4px;font-size:11px}.upload-label input{max-width:220px;font-size:10px;margin-top:6px}.slide-card{border-top:1px solid var(--line);padding-top:22px;margin-top:22px}.slide-card:first-child{border-top:0;padding-top:0;margin-top:0}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.notice{padding:13px 17px;background:#eaf8ed;color:#176428;border:1px solid #b8e5c0;border-radius:4px;margin:0 0 22px;font-size:12px}.notice.error{background:#fff1f1;color:#992626;border-color:#edc4c4}.auth{min-height:100vh;display:grid;place-items:center;padding:30px}.auth-card{max-width:440px;width:100%;background:white;border:1px solid var(--line);border-radius:7px;padding:35px}.auth-card img{display:block;width:240px;max-width:100%;margin:0 auto 30px}.auth-card h1{font-size:27px}.auth-card .btn{width:100%;margin-top:20px}.auth-card>a{display:block;text-align:center;font-size:11px;color:var(--muted);margin-top:20px}.publish-state{font-size:10px;color:var(--muted)}.check-label{display:flex;align-items:center;gap:8px}.service-title{font-weight:bold}.mobile-tabs{display:none}.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);z-index:50;max-width:90vw;padding:13px 22px;background:var(--navy);color:white;border-radius:5px;box-shadow:0 5px 25px #0b1e5530;font-size:12px}.toast.error{background:#9f2525}
@media(max-width:900px){.shell{grid-template-columns:200px 1fr}.sidebar{padding:23px 15px}.top{padding:18px 24px}.main{padding:28px 24px}.editor-layout{grid-template-columns:1fr}.service-list{grid-template-columns:repeat(2,1fr);max-height:220px;overflow:auto}.image-editor{grid-template-columns:120px 1fr}.preview,.image-empty{width:120px;height:90px}}
@media(max-width:650px){.shell{display:block}.sidebar{position:static;height:auto;padding:16px 20px}.brand{max-width:210px}.sidebar small,.side-bottom{display:none}.side-tabs{display:flex;margin-top:15px;gap:5px;overflow:auto}.side-tabs button{white-space:nowrap;font-size:11px;padding:8px 11px}.side-tabs button[aria-selected=true]{border-left:0;border-bottom:2px solid var(--green)}.top{padding:14px 20px;gap:10px;flex-wrap:wrap}.top>strong{display:none}.top div{width:100%;justify-content:space-between}.main{padding:25px 20px 60px}.heading{display:block}.heading .btn{margin-top:12px}h1{font-size:27px}.panel{padding:20px}.fields{grid-template-columns:1fr}.stats{gap:8px}.stat{padding:13px 11px}.stat b{font-size:20px}.stat span{font-size:8px;letter-spacing:.5px}.image-editor{grid-template-columns:1fr}.preview,.image-empty{width:100%;height:150px}.panel-head{flex-wrap:wrap}.publish-state{max-width:110px}.service-list{grid-template-columns:1fr 1fr}}
</style></head><body><div id="loading" class="loading tw:p-[50px] tw:text-center">Opening your content dashboard…</div>
<div id="auth" class="auth" hidden><div class="auth-card"><img src="/logo.png?v=2" alt="Likitha Sports"><p class="eyebrow">Website management</p><h1 id="auth-title">Sign in to your dashboard.</h1><p class="muted" id="auth-copy">Manage your services, homepage and carousel images.</p><div id="auth-error" class="notice error" role="alert" hidden></div><form id="auth-form"><div id="username-wrap" hidden><label for="username">Username</label><input id="username" name="username" type="text" autocomplete="username" maxlength="100" autocapitalize="none" spellcheck="false"></div><label for="password" id="password-label">Admin password</label><input id="password" type="password" autocomplete="current-password" required maxlength="200"><div id="confirm-wrap" hidden style="margin-top:15px"><label for="confirm-password">Confirm password</label><input id="confirm-password" type="password" autocomplete="new-password" maxlength="200"></div><button class="btn green" id="auth-submit" type="submit">Sign in</button></form><a id="setup-link" class="btn green" hidden>Set admin password ↗</a><a href="/">← Back to your website</a></div></div>
<div id="app" class="shell" hidden><aside class="sidebar"><a class="brand" href="/" target="_blank" rel="noopener"><img src="/logo.png?v=2" alt="Likitha Sports"></a><small>CONTENT WORKSPACE</small><nav class="side-tabs" aria-label="Dashboard sections"><button type="button" data-tab="homepage" aria-selected="true">01 &nbsp; Homepage</button><button type="button" data-tab="services" aria-selected="false">02 &nbsp; Services</button><button type="button" data-tab="carousel" aria-selected="false">03 &nbsp; Carousel</button></nav><div class="side-bottom">Your website. Your next update.<a href="/" target="_blank" rel="noopener">View live website ↗</a></div></aside><div class="workspace tw:min-w-0"><header class="top"><strong>LIKITHA / CONTENT DASHBOARD</strong><div><span id="save-state" class="publish-state">All changes published</span><button id="publish" class="btn green" type="button">Publish changes ↗</button><button id="logout" class="btn outline" type="button">Sign out</button></div></header><main class="main"><div class="heading"><div><p class="eyebrow">Keep your website moving</p><h1>Your content, in your control.</h1><p class="muted">Update your content here, then publish it to your live website.</p></div><a class="btn outline" href="/" target="_blank" rel="noopener">View website ↗</a></div><div id="editor-error" class="notice error" role="alert" hidden></div><div class="stats"><div class="stat"><b id="stat-services">—</b><span>Published services</span></div><div class="stat"><b id="stat-slides">—</b><span>Carousel slides</span></div><div class="stat"><b id="stat-updated" style="font-size:15px;line-height:2.5">—</b><span>Last published</span></div></div>
<section id="tab-homepage"><div class="panel"><div class="panel-head"><div><h2>The first impression.</h2><p class="muted">Edit the main headline and introduction on your homepage.</p></div></div><div class="fields"><div><label for="hero-line1">Headline — line 1</label><input id="hero-line1" data-hero="line1" maxlength="60"></div><div><label for="hero-line2">Headline — green line</label><input id="hero-line2" data-hero="line2" maxlength="60"></div><div class="full"><label for="hero-description">Introduction</label><textarea id="hero-description" data-hero="description" maxlength="300"></textarea><p class="hint">Keep it short and clear. Maximum 300 characters.</p></div></div></div><div class="notice">Images and edits are saved online. Uploading an image does not change your live page until you publish.</div></section>
<section id="tab-services" hidden><div class="panel-head"><div><h2>Every solution, one place.</h2><p class="muted">Choose a service to edit its text, image and visibility.</p></div><button class="btn outline" type="button" id="add-service">+ Add service</button></div><div class="editor-layout"><div class="service-list" id="service-list" aria-label="Select a service"></div><div class="panel" id="service-editor"></div></div></section>
<section id="tab-carousel" hidden><div class="panel"><div class="panel-head"><div><h2>Give your homepage a new view.</h2><p class="muted">Update slide text and images. The carousel rotates automatically.</p></div><button class="btn outline" id="add-slide" type="button">+ Add slide</button></div><div id="slides-editor"></div></div></section>
</main></div></div><div class="toast" id="toast" role="status" hidden></div>
<script>
let content=null,csrf='',currentService=0,dirty=false,setupMode=false,busy=false,uploads=0,usernameRequired=false;
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function imageUrl(image){return !image?'':image.startsWith('/media/')?image:'https://likithasports.com/assets/home/'+image}
function notify(message,error=false){$('toast').textContent=message;$('toast').classList.toggle('error',error);$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,4500)}
function markDirty(){dirty=true;$('save-state').textContent='Unpublished changes'}
function errorBox(id,message){$(id).textContent=message;$(id).hidden=!message}
async function api(path,options={}){const headers={'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{}),...options.headers};const res=await fetch(path,{credentials:'same-origin',cache:'no-store',...options,headers});const data=await res.json();if(!res.ok){if(res.status===401&&path!='/api/admin/login'){showAuth({configured:true});}throw new Error(data.error||'The request could not be completed.')}return data}
function showAuth(status){$('loading').hidden=true;$('app').hidden=true;$('auth').hidden=false;if(typeof status.username_required==='boolean')usernameRequired=status.username_required;$('username-wrap').hidden=!usernameRequired;$('username').required=usernameRequired;setupMode=!status.configured&&status.setup_allowed&&location.pathname==='/dashboard/setup';if(!status.configured&&!setupMode){$('auth-form').hidden=true;$('auth-title').textContent='One private setup step.';$('auth-copy').textContent='Create your admin password on the private setup page. Vercel sign-in is required. Then return here to sign in.';const link=$('setup-link');if(status.setup_url){link.href=status.setup_url;link.hidden=false}return}$('setup-link').hidden=true;$('auth-form').hidden=false;$('auth-title').textContent=setupMode?'Create your admin password.':'Sign in to your dashboard.';$('auth-copy').textContent=setupMode?'Choose a unique password of at least 14 characters. This setup page closes after the password is created.':'Manage your services, homepage and carousel images.';$('auth-submit').textContent=setupMode?'Create password & open dashboard':'Sign in';$('confirm-wrap').hidden=!setupMode;$('password').autocomplete=setupMode?'new-password':'current-password';$('password').minLength=setupMode?14:1;$('confirm-password').required=setupMode}
$('auth-form').addEventListener('submit',async e=>{e.preventDefault();errorBox('auth-error','');if(setupMode&&$('password').value!==$('confirm-password').value){errorBox('auth-error','The passwords do not match.');return}$('auth-submit').disabled=true;try{const result=await api(setupMode?'/api/admin/setup':'/api/admin/login',{method:'POST',body:JSON.stringify({username:$('username').value,password:$('password').value})});csrf=result.csrf;$('password').value='';$('confirm-password').value='';await openDashboard()}catch(error){errorBox('auth-error',error.message)}finally{$('auth-submit').disabled=false}});
async function openDashboard(){content=await api('/api/admin/content');dirty=false;$('auth').hidden=true;$('loading').hidden=true;$('app').hidden=false;document.querySelectorAll('[data-hero]').forEach(input=>{input.value=content.hero[input.dataset.hero]});renderServices();renderSlides();stats();$('save-state').textContent='All changes published'}
function stats(){$('stat-services').textContent=content.services.filter(s=>s.published).length;$('stat-slides').textContent=content.slides.length;$('stat-updated').textContent=content.updated_at?new Date(content.updated_at*1000).toLocaleDateString(undefined,{day:'numeric',month:'short'}):'Original content'}
document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b===button)));['homepage','services','carousel'].forEach(name=>$('tab-'+name).hidden=name!==button.dataset.tab)}));
document.querySelectorAll('[data-hero]').forEach(input=>input.addEventListener('input',()=>{content.hero[input.dataset.hero]=input.value;markDirty()}));
function imageEditor(image,kind,index){return `<div class="image-editor">${image?`<img class="preview" src="${esc(imageUrl(image))}" alt="Selected image">`:'<div class="image-empty">No image selected</div>'}<div><label class="upload-label">Upload image<input type="file" accept="image/png,image/jpeg,image/webp" data-upload="${kind}" data-index="${index}"></label><p class="hint">PNG, JPEG or WebP. Maximum 2 MB.</p>${kind==='service'&&image?`<button type="button" class="btn outline" data-clear-image="${index}" style="margin-top:8px;padding:5px 10px">Remove image</button>`:''}</div></div>`}
function renderServices(){currentService=Math.min(currentService,content.services.length-1);$('service-list').innerHTML=content.services.map((s,i)=>`<button type="button" data-service-index="${i}" class="${i===currentService?'active':''}">${esc(s.title||'New service')}<span>${s.published?'Published':'Hidden from website'}</span></button>`).join('');$('service-list').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{currentService=Number(b.dataset.serviceIndex);renderServices()}));const s=content.services[currentService];$('service-editor').innerHTML=`<div class="panel-head"><div><h2>Edit service</h2><p class="muted">Its detail page updates when you publish.</p></div><label class="check-label"><input type="checkbox" id="service-published" ${s.published?'checked':''}>Published</label></div><div class="fields"><div class="full"><label>Service name<input data-service-field="title" maxlength="100" value="${esc(s.title)}"></label></div><div><label>URL name<input data-service-field="slug" maxlength="70" pattern="[a-z0-9]+(-[a-z0-9]+)*" value="${esc(s.slug)}"></label><p class="hint">Changing this changes the service page link.</p></div><div><label>Category<select data-service-field="category"><option value="court" ${s.category==='court'?'selected':''}>Courts</option><option value="field" ${s.category==='field'?'selected':''}>Turfs & tracks</option><option value="facility" ${s.category==='facility'?'selected':''}>Facilities</option></select></label></div><div class="full"><label>Short description<textarea data-service-field="summary" maxlength="300">${esc(s.summary)}</textarea></label></div></div>${imageEditor(s.image,'service',currentService)}<div class="fields"><div class="full"><label>Project scope — one item per line<textarea data-service-field="scope" rows="4">${esc(s.scope.join('\n'))}</textarea></label><p class="hint">One to six items. Up to 180 characters per item.</p></div><div class="full"><label>Guidance for customer enquiries<textarea data-service-field="prompt" maxlength="300">${esc(s.prompt)}</textarea></label></div></div><div class="actions"><button class="btn danger" type="button" id="remove-service">Remove service from this update</button></div>`;$('service-editor').querySelectorAll('[data-service-field]').forEach(input=>input.addEventListener('input',()=>{const key=input.dataset.serviceField;s[key]=key==='scope'?input.value.split('\n').map(x=>x.trim()).filter(Boolean):input.value;markDirty()}));$('service-published').addEventListener('change',e=>{s.published=e.target.checked;markDirty();stats();renderServices()});$('remove-service').addEventListener('click',()=>{if(content.services.length===1){notify('Keep at least one service.',true);return}if(!confirm('Remove this service when you publish? You can reload the page to discard unpublished changes.'))return;content.services.splice(currentService,1);currentService=0;markDirty();stats();renderServices()});bindUploads($('service-editor'));const clear=$('service-editor').querySelector('[data-clear-image]');if(clear)clear.addEventListener('click',()=>{s.image=null;markDirty();renderServices()})}
$('add-service').addEventListener('click',()=>{if(content.services.length>=30){notify('You can add up to 30 services.',true);return}let slug='new-service',n=2;while(content.services.some(s=>s.slug===slug))slug='new-service-'+n++;content.services.push({slug,title:'New service',category:'court',image:null,summary:'Add a short description of this service.',scope:['Add your project scope'],prompt:'Tell us about your project requirements.',published:false});currentService=content.services.length-1;markDirty();renderServices();stats()});
function renderSlides(){$('slides-editor').innerHTML=content.slides.map((s,i)=>`<div class="slide-card"><div class="panel-head"><h2>Slide ${i+1}</h2><div><button class="btn outline" type="button" data-up-slide="${i}" ${i===0?'disabled':''}>↑ Move up</button> <button class="btn danger" type="button" data-remove-slide="${i}">Remove</button></div></div><div class="fields"><div><label>Title<input data-slide-field="title" data-index="${i}" maxlength="100" value="${esc(s.title)}"></label></div><div><label>Category label<input data-slide-field="category" data-index="${i}" maxlength="70" value="${esc(s.category)}"></label></div><div class="full"><label>Image description<input data-slide-field="alt" data-index="${i}" maxlength="150" value="${esc(s.alt)}"></label></div></div>${imageEditor(s.image,'slide',i)}</div>`).join('');$('slides-editor').querySelectorAll('[data-slide-field]').forEach(input=>input.addEventListener('input',()=>{content.slides[Number(input.dataset.index)][input.dataset.slideField]=input.value;markDirty()}));$('slides-editor').querySelectorAll('[data-remove-slide]').forEach(b=>b.addEventListener('click',()=>{if(content.slides.length===1){notify('Keep at least one slide.',true);return}content.slides.splice(Number(b.dataset.removeSlide),1);markDirty();renderSlides();stats()}));$('slides-editor').querySelectorAll('[data-up-slide]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.upSlide);[content.slides[i-1],content.slides[i]]=[content.slides[i],content.slides[i-1]];markDirty();renderSlides()}));bindUploads($('slides-editor'))}
$('add-slide').addEventListener('click',()=>{if(content.slides.length>=6){notify('You can add up to six slides.',true);return}content.slides.push({title:'Your next sports space.',category:'SPORTS INFRASTRUCTURE',image:'football-truf.webp',alt:'Football turf'});markDirty();renderSlides();stats()});
function bindUploads(root){root.querySelectorAll('[data-upload]').forEach(input=>input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){notify('Choose a PNG, JPEG or WebP image under 2 MB.',true);input.value='';return}const kind=input.dataset.upload,index=Number(input.dataset.index),target=kind==='service'?content.services[index]:content.slides[index];input.disabled=true;uploads++;$('publish').disabled=true;try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('The image could not be read.'));reader.readAsDataURL(file)});const result=await api('/api/admin/upload',{method:'POST',body:JSON.stringify({data})});target.image=result.url;markDirty();if(kind==='service')renderServices();else renderSlides();notify('Image uploaded. Publish your changes to display it on the website.')}catch(error){notify(error.message,true)}finally{uploads--;$('publish').disabled=uploads>0;input.disabled=false}}))}
$('publish').addEventListener('click',async()=>{if(busy||uploads)return;errorBox('editor-error','');busy=true;$('publish').disabled=true;$('publish').textContent='Publishing…';try{const result=await api('/api/admin/content',{method:'POST',body:JSON.stringify(content)});content.revision=result.revision;content.updated_at=result.updated_at;dirty=false;$('save-state').textContent='All changes published';stats();notify('Your website content is published.')}catch(error){errorBox('editor-error',error.message)}finally{busy=false;$('publish').disabled=false;$('publish').textContent='Publish changes ↗'}});
$('logout').addEventListener('click',async()=>{if(dirty&&!confirm('Sign out and discard unpublished edits?'))return;try{await api('/api/admin/logout',{method:'POST',body:'{}'});dirty=false;csrf='';location.href='/dashboard'}catch(error){notify(error.message,true)}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
(async()=>{try{const status=await api('/api/admin/status');if(status.authenticated){csrf=status.csrf;await openDashboard()}else showAuth(status)}catch(error){$('loading').hidden=true;showAuth({configured:true});$('auth-form').hidden=true;errorBox('auth-error',error.message)}})();
</script></body></html>'''
